<?php
require_once '../includes/auth.php';requireLogin();requireTenantContext();$tenantId=getCurrentTenantId();$rows=[];$q=$conn->query("SHOW TABLES LIKE 'wallet_transactions'");if($q&&$q->num_rows){$st=$conn->prepare("SELECT * FROM wallet_transactions WHERE tenant_id=? ORDER BY id DESC LIMIT 200");$st->bind_param("i",$tenantId);$st->execute();$r=$st->get_result();while($x=$r->fetch_assoc())$rows[]=$x;}
$pageTitle='Wallet Transactions';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Wallet Transactions</h2><?php if(!$rows):?><p>No wallet transactions found.</p><?php else:?><div class="table-responsive"><table><thead><tr><?php foreach(array_keys($rows[0]) as $k):?><th><?=e(ucwords(str_replace('_',' ',$k)))?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $x):?><tr><?php foreach($x as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require_once '../includes/footer.php';?>